.kl-more-fade.--kl-more-g:
var(--kl-more-s) 0%, color-mix(in oklab, var(--kl-more-s) 70%, transparent) 20%,
      color-mix(in oklab, var(--kl-more-s) 42%, transparent) 42%,
      color-mix(in oklab, var(--kl-more-s) 18%, transparent) 68%, transparent 100%

.kl-dock-min.width:
max(
      var(--kl-dock-a),
      calc(
        var(--kl-dock-w, 0px) - 100000 *
          min(1px, max(0px, (var(--kl-dock-a) - var(--kl-dock-w, 0px) + var(--kl-snap)) * 1000))
      )
    )

.kl-dock-fit.--kl-dock-on:
calc(
      100000 *
        min(
          1px,
          max(
            0px,
            (var(--kl-snap) - max(var(--kl-dock-a) - var(--kl-dock-w), var(--kl-dock-w) - var(--kl-dock-a))) * 1000
          )
        )
    )

.kl-dock-fit.width:
clamp(
      calc(var(--kl-dock-w) - var(--kl-dock-on)),
      var(--kl-dock-a),
      calc(var(--kl-dock-w) + var(--kl-dock-on))
    )

.kl-frame::after, .kl-ctl::after.background:
linear-gradient(
        to bottom right,
        transparent calc(var(--kl-d) - 0.5px),
        var(--kl-cut-line, var(--kl-line)) calc(var(--kl-d) + 0.25px),
        var(--kl-cut-line, var(--kl-line)) calc(var(--kl-d) + var(--kl-cut-w, var(--kl-bw)) - 0.25px),
        transparent calc(var(--kl-d) + var(--kl-cut-w, var(--kl-bw)) + 0.5px)
      )

.kl-frame:is([dir=\"rtl\"], [dir=\"rtl\".background:
linear-gradient(
        to bottom left,
        transparent calc(var(--kl-d) - 0.5px),
        var(--kl-cut-line, var(--kl-line)) calc(var(--kl-d) + 0.25px),
        var(--kl-cut-line, var(--kl-line)) calc(var(--kl-d) + var(--kl-cut-w, var(--kl-bw)) - 0.25px),
        transparent calc(var(--kl-d) + var(--kl-cut-w, var(--kl-bw)) + 0.5px)
      )
